import {advancedLessons} from './advanced-lessons.js';
const pilotLessons = {
  vectors: {
    name:'Vectors & combinations', time:'~8 MINUTES', title:'Small arrows.<br>Big ideas.', intro:'A vector is a step in a direction. Put a few steps together and something interesting happens. Let’s start with a picture.', experiment:'What can two vectors make?', controls:'Mix your vectors',
    discovery:'Try making a negative. A negative coefficient reverses an arrow; its absolute value determines how much the arrow stretches.', prompt:'Try a = 0, then a = −1. What changes—and what stays the same?',
    notesTitle:'A vector is more than an arrow.',
    notes:`<p>In the coordinate plane, a vector <strong>(x, y)</strong> describes a displacement: x units horizontally and y units vertically. The arrow is a geometric picture of that vector.</p><div class="math">v = (1, 2)<br>2v = (2, 4)<br>−v = (−1, −2)</div><h3>Scale first. Then add.</h3><p>A <strong>scalar</strong> is a number. Multiplying a vector by a scalar scales its length by the absolute value of that number. A negative scalar also reverses its orientation; zero produces the zero vector, which has no direction.</p><p>Vector addition combines the corresponding coordinates. Geometrically, place the second arrow at the tip of the first. The result connects the original starting point to the final endpoint.</p><div class="math">a v₁ + b v₂<br>= (a x₁ + b x₂, a y₁ + b y₂)</div><p>This is a <strong>linear combination</strong>. The dashed arrows in the playground show the head-to-tail construction.</p><h3>Try explaining it</h3><p>Why does multiplying by −2 double the length but reverse the orientation? Use coordinates and the diagram to explain the same result.</p>`,
    questions:[
      {title:'Predict before you calculate.',context:'If v = (1, 2), what is −2v?',options:['(−2, −4)','(−2, 4)','(2, 4)'],correct:0,feedback:['Exactly. Both coordinates are multiplied by −2: the length doubles and the arrow reverses.','The scalar multiplies both coordinates. The second coordinate must also change sign.','That is 2v. The negative sign reverses the orientation as well.'],hint:'Multiply each coordinate by the same scalar, including its sign.'},
      {title:'One idea, a new pair of vectors.',context:'Let u = (2, 1) and v = (−1, 3). Where does u + 2v end?',options:['(0, 7)','(1, 4)','(2, 7)'],correct:0,feedback:['Yes. (2, 1) + (−2, 6) = (0, 7). Scaling happens before addition.','That is u + v. First double v, then add its coordinates to u.','The horizontal component also changes: 2 + 2 × (−1) = 0.'],hint:'First find 2v = (−2, 6). Then add u coordinate by coordinate.'}
    ]
  },
  span: {
    name:'Span & independence', time:'~10 MINUTES', title:'How far can<br>two arrows take you?', intro:'Some pairs of vectors can take you anywhere on the plane. Others keep you on a single line. Discover what makes the difference.',experiment:'A whole plane—or just a line?',controls:'Explore the possibilities',
    discovery:'The green shading shows the span, using any real coefficients—not only the range of these sliders. Parallel vectors share one line of possibilities.',prompt:'Choose “Independent pair”, then try “Parallel pair”. Can both reach the target (2, 1)?',
    notesTitle:'More arrows don’t always mean more freedom.',
    notes:`<p>The <strong>span</strong> of a set of vectors is the set of all their linear combinations, using any real coefficients. The sliders show only a small window of these possibilities.</p><div class="math">span(v₁, v₂) = {a v₁ + b v₂ : a, b ∈ ℝ}</div><p>Two nonparallel vectors in the plane span the entire plane. Two parallel vectors, with at least one nonzero vector, span a line. Two zero vectors span only the origin.</p><h3>Independence is about coefficients</h3><p>Vectors are <strong>linearly independent</strong> when the only way to make the zero vector from them is to use all-zero coefficients.</p><div class="math">a v₁ + b v₂ = (0, 0)<br>implies a = b = 0</div><p>The vectors themselves do <strong>not</strong> have to be zero. This condition says there is no nontrivial cancellation between them.</p><h3>A concrete dependence</h3><p>If v₁ = (1, 1) and v₂ = (2, 2), then 2v₁ − v₂ = (0, 0). The coefficients 2 and −1 are not both zero, so this pair is dependent.</p><h3>A bridge to matrices</h3><p>Put the vectors in the <strong>columns</strong> of a 2 × 2 matrix. Its rank is the dimension of their span: zero, one, or two. For this square matrix, a nonzero determinant means rank two and independence.</p>`,
    questions:[
      {title:'Can this pair reach the target?',context:'v₁ = (1, 1), v₂ = (2, 2). Can any real a and b give a v₁ + b v₂ = (2, 1)?',options:['No. Every reachable point has equal coordinates.','Yes. Two vectors can always reach any point in 2D.','Yes, if we use sufficiently large coefficients.'],correct:0,feedback:['Exactly. Every result is (a + 2b, a + 2b). Changing the coefficient range cannot escape that line.','Two vectors can span the plane only when they are independent. Here v₂ = 2v₁.','Larger coefficients move farther along the same line. They cannot make the coordinates unequal.'],hint:'Write out both coordinates of a(1, 1) + b(2, 2). Are they ever different?'},
      {title:'What does independence actually tell us?',context:'For independent vectors u and v, the equation a u + b v = (0, 0) means…',options:['a = b = 0','u = v = (0, 0)','a + b = 0, with any values of a and b'],correct:0,feedback:['Right. Independence restricts the coefficients in a zero combination, not the vectors themselves.','It is the coefficients that must be zero. A pair containing a zero vector is dependent.','Opposite coefficients cancel only when the weighted vectors line up appropriately. Independent vectors cannot cancel with nonzero coefficients.'],hint:'The definition rules out a nontrivial linear combination that equals zero.'}
    ]
  },
  transformations: {
    name:'Matrix transformations',time:'~10 MINUTES',title:'A matrix moves<br>the whole picture.',intro:'Think of a matrix as a rule for moving every vector. Stretch, rotate, shear—or flatten an entire plane into a line.',experiment:'Change the matrix. Watch space move.',controls:'Your transformation',
    discovery:'The first column tells you where (1, 0) goes. The second tells you where (0, 1) goes. Together, those two images determine the entire transformation.',prompt:'Try “Collapse to a line”. What happens to area? What do you notice about the two columns?',
    notesTitle:'Two columns. One rule for every vector.',
    notes:`<p>A real 2 × 2 matrix defines a <strong>linear transformation</strong> of the plane. It preserves vector addition and scalar multiplication, and always sends the origin to itself.</p><div class="math">A = [[a, b], [c, d]]<br>A(x, y) = (ax + by, cx + dy)</div><h3>Read the columns</h3><p>The first column is A(1, 0), the image of the first standard basis vector. The second is A(0, 1). Every vector (x, y) is x(1, 0) + y(0, 1), so its image is the same combination of the matrix’s columns.</p><h3>Area and the determinant</h3><p>The determinant is ad − bc. Its <strong>absolute value</strong> is the area scale factor. A negative determinant reverses orientation. A determinant of zero means the plane collapses to a line or point, and the transformation cannot be inverted.</p><div class="math">det(A) = ad − bc<br>area scale = |det(A)|</div><h3>Not every movement is linear</h3><p>A translation by a nonzero vector moves the origin, so it is not a linear transformation of the plane. Rotations about the origin, reflections through lines through the origin, and shears are linear.</p><p>In the diagram, faint gray lines show the original grid. Green lines show its transformed image. The orange arrow is Av; the dashed gray arrow is v.</p>`,
    questions:[
      {title:'Read the matrix as a transformation.',context:'For A = [[1, 1], [0, 1]], where does the vector (0, 1) go?',options:['(1, 1)','(1, 0)','(0, 1)'],correct:0,feedback:['Yes. The second column is the image of (0, 1). This shear moves its endpoint to (1, 1).','That is the first column: the image of (1, 0). We need the second column.','This is the original vector. The shear adds its y-coordinate to its x-coordinate.'],hint:'Multiply the matrix by (0, 1), or just read its second column.'},
      {title:'What does a negative determinant mean?',context:'A = [[−1, 0], [0, 1]] has determinant −1. What happens to a unit square?',options:['Its area stays 1, and its orientation reverses.','Its area becomes −1.','It collapses into a line.'],correct:0,feedback:['Exactly. This reflection preserves area because |det(A)| = 1, while reversing orientation.','Area is nonnegative. The sign describes orientation; the absolute value gives the area scale.','Collapse happens when the determinant is zero. Here the transformation is invertible.'],hint:'Separate the sign of the determinant from its absolute value.'}
    ]
  }
};

export const courseOrder=['vectors','matrices','transformations','span','elimination','solutions','vector-spaces','dependence','basis','subspaces','homogeneous','matrix-spaces','nullspace','orthogonality','projections','least-squares','determinants','eigenvalues','decompositions','svd','applications'];
const all={...pilotLessons,...advancedLessons};
Object.assign(all.vectors,{group:'01 · Foundations',prereq:[],lab:'vectors',initial:{u:[1,2],v:[2,0],a:1,b:1}});
Object.assign(all.span,{name:'Span & dimension',group:'01 · Foundations',prereq:['vectors','transformations'],lab:'span',initial:{u:[1,1],v:[2,2],a:1,b:0}});
Object.assign(all.transformations,{group:'01 · Foundations',prereq:['matrices'],lab:'transformations',initial:{u:[1,1],m:[1,1,0,1]}});
export const lessons=Object.fromEntries(courseOrder.map(id=>[id,all[id]]));
